import "react-multi-carousel/lib/styles.css";
import { Container, Row, Col } from "react-bootstrap";
import colorSharp from "../assets/images/color-sharp.png";
import reactimg from "../assets/images/React.png"
import javaimg from "../assets/images/java.png"
import pythonimg from "../assets/images/python.png"
import htmlimg from "../assets/images/html.png"
import djangoimg from "../assets/images/django.png"
import dotnet from "../assets/images/dot net.png"
import "react-circular-progressbar/dist/styles.css";
export const Skills = () => {
  const skills = [
    {
      name: "REACT",
      image: reactimg,
    },
    {
      name: "JAVA",
      image: javaimg,
    },
    {
      name: "PYTHON",
      image: pythonimg,
    },
    {
      name: "HTML,CSS,JS",
      image: htmlimg,
    },
    {
      name: "DJANGO",
      image: djangoimg,
    },
    {
      name: "ASP .NET MVC",
      image: dotnet,
    },
  ];
  return (
    <section className="skill" id="skills">
      <Container>
        <Row>
          <Col>
            <div className="skills-bx">
              <h2>Skills</h2>
              <p>I have experience in following skills.</p>
            </div>
          </Col>
        </Row>
        <Row>
          {skills.map((skill) => {
            return (
              <Col md={3} xs={6} sm={6} lg={2}>
                <div className="item">
                  <img src={skill.image} className={skill.image===reactimg?"react":""} alt="logo" />
                  <br />
                  <h6>{skill.name}</h6>
                </div>
              </Col>
            );
          })}
        </Row>
      </Container>
      <img src={colorSharp} className="background-image-left" alt="" />
    </section>
  );
};
